import {image,makeCanvas,splitGridRects} from './core.js';
export async function createSplitEditor(host,blob,onChange=()=>{}){
 const bitmap=await image(blob),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height)),canvas=makeCanvas(Math.round(bitmap.width*scale),Math.round(bitmap.height*scale));canvas.id='split-canvas';canvas.setAttribute('aria-label','اسحب خطوط التقسيم لتحديد أجزاء الصفحة');host.replaceChildren(canvas);
 let lines=[],active='',rtl=true,drag=null,disposed=false,serial=0;
 const rects=()=>splitGridRects(bitmap.width,bitmap.height,lines.filter(l=>l.axis==='vertical').map(l=>l.position),lines.filter(l=>l.axis==='horizontal').map(l=>l.position),rtl);
 function paint(){if(disposed)return;const ctx=canvas.getContext('2d'),r=canvas.getBoundingClientRect(),unit=canvas.width/Math.max(1,r.width);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const pieces=rects();ctx.font=`bold ${18*unit}px Arial`;ctx.textAlign='center';ctx.textBaseline='middle';pieces.forEach((p,i)=>{const x=(p.x+p.w/2)*scale,y=(p.y+p.h/2)*scale;ctx.fillStyle='#ffffffdd';ctx.beginPath();ctx.arc(x,y,15*unit,0,Math.PI*2);ctx.fill();ctx.fillStyle='#163f35';ctx.fillText(i+1,x,y);});lines.forEach((l,i)=>{ctx.strokeStyle=l.id===active?'#f58b19':'#137a5b';ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=(l.id===active?4:2)*unit;const vertical=l.axis==='vertical',p=l.position*(vertical?canvas.width:canvas.height);ctx.beginPath();ctx.moveTo(vertical?p:0,vertical?0:p);ctx.lineTo(vertical?p:canvas.width,vertical?canvas.height:p);ctx.stroke();const x=vertical?p:canvas.width*.12,y=vertical?canvas.height*.12:p;ctx.beginPath();ctx.arc(x,y,14*unit,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.font=`bold ${14*unit}px Arial`;ctx.fillText(i+1,x,y);});const previews=pieces.map(p=>{const ratio=Math.min(130/p.w,130/p.h,1),c=makeCanvas(Math.max(1,Math.round(p.w*ratio)),Math.max(1,Math.round(p.h*ratio)));c.getContext('2d').drawImage(bitmap,p.x,p.y,p.w,p.h,0,0,c.width,c.height);return c;});onChange({lines:lines.map(l=>({...l})),active,rects:pieces,previews});}
 function point(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height,r};}
 canvas.onpointerdown=e=>{const p=point(e),nearest=lines.map(l=>({l,d:Math.abs(l.position-(l.axis==='vertical'?p.x:p.y))*(l.axis==='vertical'?p.r.width:p.r.height)})).sort((a,b)=>a.d-b.d)[0];if(!nearest||nearest.d>28)return;e.preventDefault();active=nearest.l.id;drag=e.pointerId;canvas.setPointerCapture(e.pointerId);paint();};
 canvas.onpointermove=e=>{if(e.pointerId!==drag)return;e.preventDefault();const p=point(e),l=lines.find(l=>l.id===active);l.position=Math.max(.02,Math.min(.98,l.axis==='vertical'?p.x:p.y));paint();};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
 function validate(next){splitGridRects(bitmap.width,bitmap.height,next.filter(l=>l.axis==='vertical').map(l=>l.position),next.filter(l=>l.axis==='horizontal').map(l=>l.position));}
 function preset(axis,count){lines=Array.from({length:count-1},(_,i)=>({id:String(++serial),axis,position:(i+1)/count}));active=lines[0]?.id||'';paint();}
 preset('vertical',2);
 return{preset,select(id){active=id;paint();},add(axis){const positions=lines.filter(l=>l.axis===axis).map(l=>l.position).sort((a,b)=>a-b),bounds=[0,...positions,1];let a=0,b=1,gap=0;for(let i=1;i<bounds.length;i++)if(bounds[i]-bounds[i-1]>gap){a=bounds[i-1];b=bounds[i];gap=b-a;}const l={id:String(++serial),axis,position:(a+b)/2},next=[...lines,l];validate(next);lines=next;active=l.id;paint();},update(values){const next=lines.map(l=>l.id===active?{...l,...values}:l);validate(next);lines=next;paint();},remove(){lines=lines.filter(l=>l.id!==active);active=lines.at(-1)?.id||'';paint();},order(value){rtl=value;paint();},exportCanvases(){return rects().map(r=>{const c=makeCanvas(r.w,r.h);c.getContext('2d').drawImage(bitmap,r.x,r.y,r.w,r.h,0,0,r.w,r.h);return c;});},destroy(){disposed=true;drag=null;bitmap.close();}};
}
